package com.myfit.tracker.domain

import android.content.Context
import com.myfit.tracker.data.db.SetRow
import com.myfit.tracker.data.db.SetType
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import org.json.JSONObject

/**
 * R31 calisthenics skill tree. Chains of progressions (push-up → one-arm push-up, dead hang → one-arm chin-up …)
 * loaded from assets/calisthenics.json (generated by tools/cali/gen.py).
 *
 * Progression follows the Recommended Routine idea: work your current step at 3 sets of [Step.start], and when a
 * logged workout has 3 working sets at [Step.goal] or more (reps, or seconds for holds) the step is mastered and the
 * next one unlocks. Everything is read from the sets you actually log — nothing is estimated.
 */
object Cali {
    data class Step(
        val key: String, val name: String, val hold: Boolean, val start: Int, val goal: Int,
        val equipment: String, val props: List<String>, val poses: List<String>, val cue: String,
    ) {
        val uuid get() = "fedb:$key"
        fun target() = if (hold) "3 × ${start}–${goal} s" else "3 × ${start}–${goal}"
        fun goalText() = if (hold) "3 × $goal s" else "3 × $goal"
        /** Gear the step can't be done without (used to swap in an easier step when you don't have it). */
        val needs: String? get() = when {
            "Pull-up bar" in equipment -> "bar"
            "Parallel bars" in equipment || "rings" in equipment.lowercase() -> "dip"
            else -> null
        }
    }
    data class Chain(val id: String, val name: String, val sub: String, val color: Long, val steps: List<Step>)
    data class Placement(val by: String, val at: List<Pair<Int, Int>>)
    class Data(val chains: List<Chain>, val poses: Map<String, FloatArray>, val placement: Map<String, Placement>) {
        val byKey: Map<String, Pair<Chain, Int>> = chains.flatMap { c -> c.steps.mapIndexed { i, s -> s.key to (c to i) } }.toMap()
        fun chain(id: String) = chains.firstOrNull { it.id == id }
        fun step(key: String?) = key?.let { byKey[it] }?.let { (c, i) -> c.steps[i] }
    }

    @Volatile private var cache: Data? = null
    fun data(ctx: Context): Data = cache ?: synchronized(this) {
        cache ?: load(ctx).also { cache = it }
    }

    private fun load(ctx: Context): Data {
        val o = JSONObject(ctx.assets.open("calisthenics.json").bufferedReader().use { it.readText() })
        fun strs(a: org.json.JSONArray) = (0 until a.length()).map { a.getString(it) }
        val chains = o.getJSONArray("chains").let { a ->
            (0 until a.length()).map { i ->
                val c = a.getJSONObject(i)
                val steps = c.getJSONArray("steps").let { sa ->
                    (0 until sa.length()).map { j ->
                        val s = sa.getJSONObject(j)
                        Step(s.getString("k"), s.getString("n"), s.getString("t") == "hold", s.getInt("start"), s.getInt("goal"),
                            s.getString("eq"), strs(s.getJSONArray("pr")), strs(s.getJSONArray("p")), s.getString("cue"))
                    }
                }
                Chain(c.getString("id"), c.getString("name"), c.getString("sub"), 0xFF000000 or c.getString("color").removePrefix("#").toLong(16), steps)
            }
        }
        val poses = o.getJSONObject("poses").let { p ->
            p.keys().asSequence().associateWith { k -> p.getJSONArray(k).let { a -> FloatArray(a.length()) { a.getDouble(it).toFloat() } } }
        }
        val placement = o.getJSONObject("placement").let { p ->
            p.keys().asSequence().associateWith { k ->
                val x = p.getJSONObject(k)
                Placement(x.getString("by"), x.getJSONArray("at").let { a -> (0 until a.length()).map { a.getJSONArray(it).let { e -> e.getInt(0) to e.getInt(1) } } })
            }
        }
        return Data(chains, poses, placement)
    }

    // ------------------------------------------------------------------ state

    /** Where you are: current step per chain, steps mastered (from your logs), and whether you've placed yourself. */
    data class State(val current: Map<String, Int>, val mastered: Set<String>, val placed: Boolean, val gear: Set<String>) {
        fun cur(c: Chain) = (current[c.id] ?: 0).coerceIn(0, c.steps.lastIndex)
        fun done(c: Chain) = c.steps.last().key in mastered
    }
    data class Unlock(val chain: Chain, val from: Step, val to: Step?)

    private fun sp(c: Context) = c.applicationContext.getSharedPreferences("cali", Context.MODE_PRIVATE)
    private val _state = MutableStateFlow<State?>(null)
    val state: StateFlow<State?> = _state

    fun read(ctx: Context): State {
        val p = sp(ctx); val d = data(ctx)
        return State(
            d.chains.associate { it.id to p.getInt("cur:${it.id}", 0) },
            p.getStringSet("mastered", emptySet())!!.toSet(),
            p.getBoolean("placed", false),
            p.getStringSet("gear", setOf("bar", "dip"))!!.toSet(),
        ).also { _state.value = it }
    }

    fun setCurrent(ctx: Context, chain: String, idx: Int) { sp(ctx).edit().putInt("cur:$chain", idx).apply(); read(ctx) }
    fun setGear(ctx: Context, gear: Set<String>) { sp(ctx).edit().putStringSet("gear", gear).apply(); read(ctx) }

    /** Level test answers → starting step for every chain. Values: pushups, pullups, hang (s), squats, plank (s). */
    fun place(ctx: Context, v: Map<String, Int>) {
        val d = data(ctx); val e = sp(ctx).edit()
        d.chains.forEach { c ->
            val pl = d.placement[c.id] ?: return@forEach
            val x = v[pl.by] ?: 0
            var idx = pl.at.firstOrNull { x >= it.first }?.second ?: 0
            if (c.id == "pull" && (v["pullups"] ?: 0) == 0) idx = when { (v["hang"] ?: 0) >= 30 -> 2; (v["hang"] ?: 0) >= 10 -> 1; else -> 0 }
            e.putInt("cur:${c.id}", idx.coerceIn(0, c.steps.lastIndex))
        }
        e.putBoolean("placed", true).apply()
        read(ctx)
    }

    /** Best working sets per logged session for one exercise, newest session first (reps or seconds). */
    fun sessions(rows: List<SetRow>, exId: Long, hold: Boolean): List<List<Int>> =
        rows.filter { it.exerciseId == exId && it.setType != SetType.WARMUP }
            .groupBy { it.workoutId }.entries.sortedByDescending { e -> e.value.maxOf { it.completedAt } }
            .map { (_, l) -> l.mapNotNull { if (hold) it.durationSec?.toInt() else it.reps }.filter { it > 0 } }
            .filter { it.isNotEmpty() }

    /** Mastered = some session has 3 working sets at the goal or better. */
    fun meets(s: Step, sessions: List<List<Int>>) = sessions.any { l -> l.count { it >= s.goal } >= 3 }

    /**
     * Read your history, record newly mastered steps, move each chain forward past mastered steps, and award stars
     * (once per step, via the Arena ledger). Returns the unlocks to celebrate.
     */
    fun sync(ctx: Context, rows: List<SetRow>, idByUuid: Map<String, Long>): List<Unlock> {
        val d = data(ctx); val st = read(ctx); val p = sp(ctx)
        val mastered = st.mastered.toMutableSet()
        val out = ArrayList<Unlock>()
        val e = p.edit()
        d.chains.forEach { c ->
            c.steps.forEach { s ->
                val id = idByUuid[s.uuid] ?: return@forEach
                if (s.key !in mastered && meets(s, sessions(rows, id, s.hold))) {
                    mastered += s.key
                    val idx = c.steps.indexOf(s)
                    com.myfit.tracker.ui.arena.ArenaProgress.grant(ctx, "cali:${s.key}", 4 + idx, "Mastered ${s.name}")
                    if (idx == c.steps.lastIndex) com.myfit.tracker.ui.arena.ArenaProgress.grant(ctx, "cali:chain:${c.id}", 15, "Completed the ${c.name} chain")
                }
            }
            var cur = st.cur(c)
            val start = cur
            while (cur < c.steps.lastIndex && c.steps[cur].key in mastered) cur++
            if (cur != start) {
                e.putInt("cur:${c.id}", cur)
                out += Unlock(c, c.steps[cur - 1], c.steps[cur])
            } else if (cur == c.steps.lastIndex && c.steps[cur].key in mastered && c.steps[cur].key !in st.mastered) {
                out += Unlock(c, c.steps[cur], null)
            }
        }
        e.putStringSet("mastered", mastered)
        if (out.isNotEmpty()) e.putStringSet("party", pending(ctx) + out.map { "${it.chain.id}|${it.from.key}|${it.to?.key ?: ""}" })
        e.apply()
        read(ctx)
        return out
    }

    /** Unlocks recorded by [sync] (from any screen) that haven't been celebrated yet; clears them. */
    fun takePending(ctx: Context): List<Unlock> {
        val d = data(ctx)
        val out = pending(ctx).mapNotNull { e ->
            val p = e.split('|'); if (p.size < 3) return@mapNotNull null
            val c = d.chain(p[0]) ?: return@mapNotNull null
            Unlock(c, d.step(p[1]) ?: return@mapNotNull null, d.step(p[2].ifEmpty { null }))
        }.sortedBy { u -> d.chains.indexOf(u.chain) }
        setPending(ctx, emptySet())
        return out
    }

    /** Highest mastered step index in a chain (−1 when none) — used by badges. */
    fun best(c: Chain, mastered: Set<String>) = c.steps.indexOfLast { it.key in mastered }

    // ------------------------------------------------------------------ today's session

    data class Item(val chain: Chain, val step: Step, val group: Int?)

    /**
     * Today's routine from your current steps (Recommended Routine pairing): pull + squat, dip + hinge, row + push
     * as supersets, then core and handstand. Steps needing gear you don't have drop back to the hardest step you can do.
     */
    fun session(ctx: Context, st: State = read(ctx)): List<Item> {
        val d = data(ctx)
        fun pick(id: String): Pair<Chain, Step>? {
            val c = d.chain(id) ?: return null
            val i = (st.cur(c) downTo 0).firstOrNull { c.steps[it].needs.let { n -> n == null || n in st.gear } } ?: return null
            return c to c.steps[i]
        }
        val pairs = listOf("pull" to "legs", "dip" to "hinge", "row" to "push")
        val out = ArrayList<Item>()
        var g = 1
        pairs.forEach { (a, b) ->
            val x = pick(a); val y = pick(b)
            if (x != null && y != null) { out += Item(x.first, x.second, g); out += Item(y.first, y.second, g); g++ }
            else listOfNotNull(x, y).forEach { out += Item(it.first, it.second, null) }
        }
        listOf("core", "hand").forEach { id -> pick(id)?.let { out += Item(it.first, it.second, null) } }
        return out
    }

    const val REST = 90
    fun templateId(ctx: Context) = sp(ctx).getLong("tpl", -1L).takeIf { it > 0 }
    fun setTemplateId(ctx: Context, id: Long) = sp(ctx).edit().putLong("tpl", id).apply()
    /** Steps unlocked but not yet celebrated (shown once on the Calisthenics screen). */
    fun pending(ctx: Context) = sp(ctx).getStringSet("party", emptySet())!!.toSet()
    fun setPending(ctx: Context, keys: Set<String>) = sp(ctx).edit().putStringSet("party", keys).apply()
}
